The issue is that `DataFrame.append()` was removed in pandas 2.x. I'll fix `sales/report.py` to use `pd.concat()` instead.
### FILE: sales/report.py
```python
"""Build a sales report table."""
import pandas as pd

from .clean import normalize


def add_row(df, row):
    new_row = pd.DataFrame([normalize(row)])
    return pd.concat([df, new_row], ignore_index=True)


def build_report(rows):
    df = pd.DataFrame(columns=["name", "qty"])
    for row in rows:
        df = add_row(df, row)
    return df


def total_qty(df) -> int:
    return int(df["qty"].sum())

